-- R2B audited deal creation and lifecycle transitions.
CREATE OR REPLACE FUNCTION public.mmhr_record_deal(payload jsonb, correlation_id uuid, idempotency_key uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE context record; receipt jsonb; deal public.deals%ROWTYPE; v_org uuid; v_actor uuid; v_id uuid; v_action text; v_revision integer; v_vendor uuid; v_product uuid; v_stage text; v_status text;
BEGIN
 IF jsonb_typeof(payload)<>'object' OR coalesce(payload->>'action','') NOT IN ('create','transition') OR coalesce(payload->>'organizationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'dealId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'actorIdentityId','') !~ '^[0-9a-fA-F-]{36}$' OR correlation_id IS NULL OR idempotency_key IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid deal input'; END IF;
 v_org:=(payload->>'organizationId')::uuid; v_actor:=(payload->>'actorIdentityId')::uuid; v_id:=(payload->>'dealId')::uuid; v_action:=payload->>'action'; SELECT * INTO context FROM mmhr_private.r1_start_security_command('workspace.access',v_org,'Record deal',correlation_id,idempotency_key); IF v_actor<>context.actor_identity_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Security command denied'; END IF; receipt:=mmhr_private.r1_checked_receipt(context.actor_identity_id,'r2b.deal',idempotency_key,payload); IF receipt IS NOT NULL THEN RETURN jsonb_build_object('dealId',receipt->>'entity_id','organizationId',v_org,'outcomeCode','replayed','correlationId',correlation_id); END IF;
 IF v_action='create' THEN
   IF payload->>'stage' <> 'lead' OR payload->>'status' <> 'open' OR coalesce(payload->>'ownerIdentityId','') !~ '^[0-9a-fA-F-]{36}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid deal create'; END IF;
   v_vendor:=NULLIF(payload->>'vendorOrganizationId','')::uuid; v_product:=NULLIF(payload->>'productId','')::uuid;
   IF v_vendor=v_org OR (v_product IS NOT NULL AND v_vendor IS NULL) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid deal links'; END IF;
   IF v_vendor IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.orgs o WHERE o.id=v_vendor AND o.type='vendor' AND o.status='active') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Deal vendor denied'; END IF;
   IF v_product IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.products p WHERE p.organization_id=v_org AND p.id=v_product AND (v_vendor IS NULL OR p.vendor_profile_id IN (SELECT vp.id FROM public.vendor_profiles vp WHERE vp.organization_id=v_vendor))) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Deal product denied'; END IF;
   INSERT INTO public.deals(id,organization_id,vendor_organization_id,product_id,owner_identity_id,stage,status,expected_close_at) VALUES(v_id,v_org,v_vendor,v_product,(payload->>'ownerIdentityId')::uuid,'lead','open',NULLIF(payload->>'expectedCloseAt','')::timestamptz) RETURNING * INTO deal;
 ELSE
   v_revision:=(payload->>'expectedRevision')::integer; v_stage:=payload->>'toStage'; v_status:=payload->>'toStatus'; IF v_revision IS NULL OR v_revision<=0 OR payload->>'fromStage' IS NULL OR payload->>'fromStatus' IS NULL OR length(btrim(coalesce(payload->>'reason',''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid deal transition'; END IF;
   SELECT * INTO deal FROM public.deals WHERE id=v_id AND organization_id=v_org FOR UPDATE; IF NOT FOUND OR deal.revision<>v_revision OR deal.stage<>payload->>'fromStage' OR deal.status<>payload->>'fromStatus' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Deal transition is stale'; END IF;
   IF v_stage NOT IN ('lead','discovery','evaluation','proposal','selection','contracting','won','lost','archived') OR v_status NOT IN ('open','won','lost','archived') OR ((v_stage IN ('lead','discovery','evaluation','proposal','selection','contracting')) AND v_status<>'open') OR (v_stage='won' AND v_status<>'won') OR (v_stage='lost' AND v_status<>'lost') OR (v_stage='archived' AND v_status<>'archived') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid deal transition'; END IF;
   IF (deal.stage IN ('won','lost','archived')) OR (v_stage='lead' AND deal.stage<>'lead') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Deal transition denied'; END IF;
   UPDATE public.deals SET stage=v_stage,status=v_status,revision=revision+1,updated_at=clock_timestamp() WHERE id=v_id AND organization_id=v_org RETURNING * INTO deal;
   INSERT INTO public.deal_stage_history(id,organization_id,deal_id,from_stage,to_stage,from_status,to_status,expected_revision,actor_identity_id,occurred_at,reason,correlation_id) VALUES(gen_random_uuid(),v_org,v_id,payload->>'fromStage',v_stage,payload->>'fromStatus',v_status,v_revision,v_actor,coalesce((payload->>'occurredAt')::timestamptz,clock_timestamp()),btrim(payload->>'reason'),correlation_id);
 END IF;
 PERFORM mmhr_private.r1_finish_security_command(context.actor_identity_id,'r2b.deal','deal.'||v_action,'deal',deal.id,v_org,'Record deal',correlation_id,idempotency_key,payload,jsonb_build_object('status','completed'),jsonb_build_object('status','completed'),context.authorization_time);
 RETURN jsonb_build_object('dealId',deal.id,'organizationId',deal.organization_id,'stage',deal.stage,'status',deal.status,'revision',deal.revision,'outcomeCode','recorded','correlationId',correlation_id);
END; $$;
REVOKE ALL ON FUNCTION public.mmhr_record_deal(jsonb,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role,mmhr_worker; GRANT EXECUTE ON FUNCTION public.mmhr_record_deal(jsonb,uuid,uuid) TO authenticated;
